mapper.select:
SELECT FROM alarm a JOIN equipment e ON e.equipment_id = a.equipment_id
AND a.status IN
#{s}
AND a.equipment_id = #{equipmentId}
ORDER BY a.alarm_id DESC

mapper.update:
UPDATE alarm
SET status = 'ACK',
acked_at = SYSDATETIME(),
acked_by = #{ackedBy}
WHERE alarm_id = #{alarmId}
AND status = 'OPEN'
